apply.studio_css:
/* Typography Studio · personality=clarity · pair=ibm_plex_serif_law · ssot */
:root {
  --font-display: "IBM Plex Serif", Georgia, serif;
  --font-body: "IBM Plex Sans", "Segoe UI", system-ui, sans-serif;
  --font-sans: "IBM Plex Sans", "Segoe UI", system-ui, sans-serif;
  --type-body-lh: 1.7;
  --type-headline-lh: 1.14;
  --type-track-display: -0.02em;
  --type-track-body: 0.01em;
  --type-btn-weight: 600;
}
body {
  font-family: var(--font-body);
  font-weight: 400;
  line-height: var(--type-body-lh);
  letter-spacing: var(--type-track-body);
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
  overflow-wrap: anywhere;
  word-break: normal;
}
body .hero h1,
body .hero .hero-title,
body h1,
body .page-title,
body .section h2,
body h2,
body h3 {
  font-family: var(--font-display);
  max-width: 100%;
  overflow-wrap: anywhere;
  word-break: break-word;
  hyphens: auto;
  white-space: normal;
}
body .hero h1,
body .hero .hero-title,
body h1,
body .page-title {
  font-weight: 600;
  font-size: clamp(2.05rem, 4.2vw, 3.5rem);
  line-height: var(--type-headline-lh);
  letter-spacing: var(--type-track-display);
}
body .section h2,
body h2 {
  font-weight: 600;
  font-size: clamp(1.4rem, 2.2vw, 1.9rem);
  line-height: 1.22;
  letter-spacing: var(--type-track-display);
}
body .btn,
body button.btn,
body a.btn {
  font-family: var(--font-body);
  font-weight: var(--type-btn-weight);
  letter-spacing: 0.02em;
  white-space: normal;
  max-width: 100%;
}
@media (max-width: 720px) {
  body { line-height: 1.55; }
  body .hero h1,
  body .hero .hero-title,
  body h1 {
    font-size: clamp(1.7rem, 6vw, 2.2rem);
    letter-spacing: -0.015em;
    max-width: 100%;
  }
}

